mapper.select:
select t.prime_rate,t.prime_rate primeRate,t.order_id,t.order_id orderId,t.car_num,t.car_num
carNum,t.receivable_amount,t.receivable_amount receivableAmount,t.ps_id,t.ps_id psId,t.status_cd,t.status_cd
statusCd,t.remark,t.received_amount,t.received_amount receivedAmount,t.car_id,t.car_id carId,t.card_id,t.card_id
cardId,t.start_time,t.start_time startTime,t.cashier_id,t.cashier_id cashierId,t.end_time,t.end_time
endTime,t.state,t.community_id,t.community_id communityId,t.cashier_name,t.cashier_name cashierName,
cmc.card_name cardName,ps.num psNum,td.`name` primeRateName,t.create_time createTime
from car_month_order t
left join car_month_card cmc on t.card_id = cmc.card_id
left join parking_space ps on t.ps_id = ps.ps_id
left join t_dict td on t.prime_rate = td.status_cd and td.table_name = 'pay_fee_detail' and td.table_columns = 'prime_rate'
left join owner_car oc on t.car_id = oc.member_id and oc.status_cd = '0'
where 1 =1

    and oc.owner_id = #{ownerId}


    and t.prime_rate= #{primeRate}


    and t.order_id= #{orderId}


    and t.car_num= #{carNum}


    and t.receivable_amount= #{receivableAmount}


    and t.ps_id= #{psId}


    and t.status_cd= #{statusCd}


    and t.remark= #{remark}


    and t.received_amount= #{receivedAmount}


    and t.car_id= #{carId}


    and t.card_id= #{cardId}


    and t.start_time= #{startTime}


    and t.cashier_id= #{cashierId}


    and t.end_time= #{endTime}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.cashier_name= #{cashierName}



    and t.create_time >= #{queryStartTime}


    and t.create_time <= #{queryEndTime}

order by t.create_time desc

    limit #{page}, #{row}

